import {
  DEEP_COUSIN_COLUMN_PEOPLE,
  DEEP_COUSIN_COLUMN_RELATIONSHIPS,
  DEEP_COUSIN_COLUMN_SCENARIO,
} from './deep-cousin-column-scenario'
